 "content": "def transform(grid):
    """Tile the 8-cells with 2x2 squares and L-triominoes.

    Squares are color 1. An L is colored 2-5 according to the missing
    corner of its 2x2 bounding box: TL, BL, TR, BR respectively.
    """
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0 for _ in range(w)] for _ in range(h)]
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset(((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)))
            placements.append((1, square))
            for missing, color in [((0, 0), 2), ((1, 0), 3), ((0, 1), 4), ((1, 1), 5)]:
                cells = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2)
                                  if (dr, dc) != missing)
                placements.append((color, cells))
    by_cell = {cell: [] for cell in occupied}
    for color, cells in placements:
        if cells <= occupied:
            for cell in cells:
                by_cell[cell].append((color, cells))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for color, cells in by_cell[cell]:
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return [(color, cells)] + rest
        return None

    solution = cover(occupied)
    if solution is None:
        raise ValueError('8-cells cannot be tiled by the expected pieces')
    for color, cells in solution:
        for r, c in cells:
            out[r][c] = color
    return out

if __name__ == '__main__':
    pass
